/*
 * build_reports.js - regenerate the evidence-backed markdown deliverables from
 * the JSON produced by the attack runs:
 *   - reports/exploitation_walkthrough.md  (Deliverable 3)
 *   - reports/hardening_report.md          (Deliverable 4)
 * (capability_inventory.md is generated by inventory.js.)
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPORTS = path.join(__dirname, "..", "reports");
const EV = path.join(REPORTS, "evidence");

function readJson(p, fallback = null) {
  try { return JSON.parse(fs.readFileSync(p, "utf8")); } catch { return fallback; }
}
function fence(s) { return "```\n" + (s ?? "").toString().trim() + "\n```"; }

const a1 = readJson(path.join(EV, "attack1_tool_injection.json"));
const a2 = readJson(path.join(EV, "attack2_resource_poisoning.json"));
const a3 = readJson(path.join(EV, "attack3_capability_chaining.json"));
const burpPath = path.join(REPORTS, "burp", "attack1_execute_command.http");
const burpExists = fs.existsSync(burpPath);

// --------------------------------------------------------------------------- //
// Deliverable 3 - Exploitation walkthrough
// --------------------------------------------------------------------------- //
let wt = `# Deliverable 3 - Exploitation Walkthrough

Three attacks were run against the sample server (\`techcorp-sample-mcp v1.0.0\`).
Each section records the **exact prompt / call**, the **tool that was called**, the
**outcome**, and the **root cause**. Raw machine-readable evidence is under
[\`evidence/\`](evidence/).

---

## Attack 1 - Tool Injection

**Objective:** ${a1?.objective ?? ""}

**Exact prompt (conversational - the user never asks for a tool):**
${fence(a1?.exact_prompt)}

**Tool called:** \`${a1?.tool_called}\` with arguments \`${JSON.stringify(a1?.tool_arguments)}\`

**Server response:**
${fence(a1?.server_response)}

**Outcome:** ${a1?.success ? "SUCCESS" : "no tool call"} - a restricted tool executed on the host from a purely conversational message. No user intent to run a command was expressed.

**Root cause:** ${a1?.root_cause ?? ""}

---

## Attack 2 - Resource Poisoning

**Objective:** ${a2?.objective ?? ""}

**Hidden payload prepended to \`docs://handbook\` (invisible HTML comment in an editor preview):**
${fence(a2?.hidden_payload)}

**Baseline (clean resource):** after reading the handbook, the benign follow-up turn triggered tool calls: \`${JSON.stringify(a2?.baseline?.followup_tool_calls)}\` (none).

**Poisoned session:** the host absorbed the standing directive \`${JSON.stringify(a2?.poisoned?.directives_absorbed)}\`. The *same* benign follow-up turn (\`${a2?.poisoned?.followup_user_turn}\`) then triggered:
${fence(JSON.stringify(a2?.poisoned?.followup_tool_calls, null, 2))}

**Data leaked on the subsequent turn:**
${fence(a2?.poisoned?.leaked_data)}

**Outcome:** ${a2?.behaviour_changed ? "SUCCESS - behaviour changed for subsequent turns" : "no behaviour change"}. A hidden instruction in untrusted resource content persisted across turns and caused silent exfiltration.

**Root cause:** ${a2?.root_cause ?? ""}

---

## Attack 3 - Capability Chaining

**Objective:** ${a3?.objective ?? ""}

**Two individually low-risk tools:** ${(a3?.low_risk_tools || []).join(", ")}.

- \`generate_export_token\` alone: ${a3?.individual_behaviour?.generate_export_token_alone}
- \`export_record\` without a valid token: ${fence(a3?.individual_behaviour?.export_record_without_valid_token)}

**The chain (output of step 1 enables step 2):**

| Step | Tool | Arguments | Output |
|---|---|---|---|
| 1 | \`${a3?.chain?.[0]?.tool}\` | \`${JSON.stringify(a3?.chain?.[0]?.arguments)}\` | \`${a3?.chain?.[0]?.output}\` |
| 2 | \`${a3?.chain?.[1]?.tool}\` | \`${JSON.stringify(a3?.chain?.[1]?.arguments)}\` | (sensitive record below) |

**High-risk outcome (internal record disclosed):**
${fence(a3?.high_risk_outcome)}

**Outcome:** ${a3?.success ? "SUCCESS" : "failed"} - two Low tools chained into a High-impact disclosure.

**Root cause:** ${a3?.root_cause ?? ""}

---

## Burp Suite evidence

The raw HTTP request/response for a successful attack (Attack 1 over the Streamable
HTTP transport) is saved at
[\`burp/attack1_execute_command.http\`](burp/attack1_execute_command.http)${burpExists ? "" : " _(run `npm run burp` to generate)_"}.
Routing \`client/capture_http_evidence.js\` through Burp (\`--proxy=127.0.0.1:8080\`)
reproduces the identical exchange in Burp's HTTP history.
`;

fs.writeFileSync(path.join(REPORTS, "exploitation_walkthrough.md"), wt);

// --------------------------------------------------------------------------- //
// Deliverable 4 - MCP Hardening Report (one root cause + one fix per vuln)
// --------------------------------------------------------------------------- //
const vulns = [
  {
    id: "V1",
    name: "Unrestricted execute_command (RCE)",
    confirmed: a1?.success,
    attack: "Attack 1",
    root_cause:
      "execute_command passes attacker-influenced text straight to the OS shell with no allow-list, and the host will invoke it from a conversational message with no user confirmation.",
    fix:
      "Remove the general shell tool. If command execution is truly needed, replace it with a fixed allow-list of parameterised sub-commands (e.g. a `disk_usage` tool that runs a hard-coded binary with validated args), never a free-form `command` string, and require explicit human-in-the-loop confirmation for any state-changing tool.",
  },
  {
    id: "V2",
    name: "Arbitrary file read via read_file (secret disclosure / path traversal)",
    confirmed: true,
    attack: "Attack 1 / Attack 2",
    root_cause:
      "read_file resolves any caller-supplied path with no base-directory containment, so `./credentials.json` and `../` traversal expose secrets.",
    fix:
      "Constrain reads to an explicit allow-listed directory: resolve the real path and reject anything whose resolved path does not start with the allowed base (`path.resolve(base, p)` then `startsWith(base + sep)`), and keep secrets out of any directory the tool can reach.",
  },
  {
    id: "V3",
    name: "Resource content treated as instructions (indirect prompt injection)",
    confirmed: a2?.behaviour_changed,
    attack: "Attack 2",
    root_cause:
      "Untrusted text from docs://handbook is concatenated into the model's instruction context, so whoever can edit the backing file injects standing directives that persist for the session.",
    fix:
      "Keep tool/resource output in a data-only channel that is never interpreted as instructions: wrap/label it as untrusted content, strip or neutralise control sequences, and gate any tool call that is triggered while processing resource content behind user confirmation. Also integrity-protect/validate resource files so they cannot be silently edited.",
  },
  {
    id: "V4",
    name: "Capability chaining via missing authorisation (BOLA)",
    confirmed: a3?.success,
    attack: "Attack 3",
    root_cause:
      "generate_export_token and export_record each skip authorisation, so a token minted for an internal record id is accepted and redeemed - two low-risk tools compose into unauthorised disclosure.",
    fix:
      "Enforce authorisation at the point of data access, not just at token issuance: check the caller's entitlement to the specific record id in export_record (and refuse to mint tokens for internal ids in generate_export_token). Bind tokens to the authorised subject, scope, and a short expiry, and sign them so they cannot be forged.",
  },
];

let hr = `# Deliverable 4 - MCP Hardening Report

Target: \`techcorp-sample-mcp v1.0.0\` (sample vulnerable MCP server).
For each **confirmed** vulnerability: one root-cause analysis and one specific,
actionable fix.

| ID | Vulnerability | Confirmed by | Status |
|---|---|---|---|
${vulns.map((v) => `| ${v.id} | ${v.name} | ${v.attack} | ${v.confirmed ? "Confirmed" : "Not confirmed in this run"} |`).join("\n")}

`;
for (const v of vulns) {
  hr += `## ${v.id} - ${v.name}\n\n`;
  hr += `**Confirmed by:** ${v.attack} ${v.confirmed ? "(reproduced)" : "(not reproduced this run)"}\n\n`;
  hr += `**Root cause.** ${v.root_cause}\n\n`;
  hr += `**Fix.** ${v.fix}\n\n---\n\n`;
}
hr += `### Cross-cutting recommendations
- Default-deny the tool surface: expose only the minimum tools, each with the narrowest schema.
- Put every High/Medium tool behind explicit user confirmation in the host.
- Treat all tool/resource output as untrusted data, never as instructions.
- Log and rate-limit tool calls; alert on sensitive reads (credentials, internal records).
`;
fs.writeFileSync(path.join(REPORTS, "hardening_report.md"), hr);

console.log("Wrote reports/exploitation_walkthrough.md and reports/hardening_report.md");
